      final login = Uri.parse(url);
      final redirect = Uri.parse(login.queryParameters['client_redirect_uri']!);
      session.complete(
        redirect
            .replace(
              queryParameters: {
                'code': 'c-1044',
                'state': login.queryParameters['state']!,
