          callback.errorDescription ??
              callback.error ??
              'No authorization code received.',
        );
  return '<!doctype html><title>$title</title>'
      '<style>body{font-family:system-ui,sans-serif;max-width:36rem;margin:5rem auto;text-align:center}</style>'
