    });
    final registry = ProviderRegistry.inMemory();
    final context = await _pumpHost(tester);

    var modelsFetched = false;
    Object? flowError;
    await tester.runAsync(() async {
      unawaited(
        runAiinMobileConnect(
          context: context,
          registry: registry,
