/// null (the real sheet's canceledLogin path).
({List<Map<Object?, Object?>> argsSeen, Completer<Object?>? Function() pending})
mockAuthSessionChannel(
  void Function(
    String url,
    Map<Object?, Object?> args,
    Completer<Object?> session,
  )
